{
  "code_review_checklist": {
    "correctness": [
      "✓ Apakah logika sudah sesuai dengan spesifikasi di SRS?",
      "✓ Apakah semua edge case sudah ditangani?",
      "✓ Apakah kondisi batas (boundary) sudah dicek?"
    ],
    "reliability": [
      "✓ Apakah semua exception sudah di-handle dengan benar?",
      "✓ Apakah ada resource leak (koneksi DB, file handle tidak ditutup)?",
      "✓ Apakah ada kemungkinan null pointer / undefined access?"
    ],
    "maintainability": [
      "✓ Apakah nama variabel/fungsi deskriptif dan konsisten?",
      "✓ Apakah tidak ada magic number tanpa komentar?",
      "✓ Apakah panjang fungsi < 50 baris (Single Responsibility)?"
    ],
    "security": [
      "✓ Apakah input user sudah divalidasi dan di-sanitize?",
      "✓ Apakah tidak ada hard-coded credentials?",
      "✓ Apakah data sensitif tidak di-log?"
    ]
  }
}
